//! Differential ratchet for
//! `src/engine/battleScriptSnatchOpcode.ts`. Expected projected results,
//! controls, and exact role errors are generated by invoking the canonical
//! TypeScript opcode handler; regenerate with
//! `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-swapattackerwithtarget-vectors.mjs`.

use std::collections::BTreeSet;

use factory_core::battle_script_swapattackerwithtarget::{
    apply_battle_script_swapattackerwithtarget, BattleScriptSwapattackerwithtargetBattler,
    BattleScriptSwapattackerwithtargetControl, BattleScriptSwapattackerwithtargetOutcome,
    BattleScriptSwapattackerwithtargetRoles, BattleScriptSwapattackerwithtargetRules,
    BATTLE_SCRIPT_HITMARKER_SWAP_ATTACKER_TARGET, BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLERS,
    BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLER_COUNT,
};
use factory_core::battle_script_swapattackerwithtarget_vectors_gen::{
    BattleScriptSwapattackerwithtargetVectorCase, BattleScriptSwapattackerwithtargetVectorState,
    BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLER_DOMAIN,
    BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BRANCH_CENSUS, BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_CASES,
    BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_CATEGORY_CENSUS,
    BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_DOMAIN_CENSUS,
    BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_HIT_MARKER_EDGE_DOMAIN,
    BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_OPTIONAL_SELECTOR_DOMAIN,
    BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_VECTOR_CORPUS_SHA256,
};

fn rules(
    value: BattleScriptSwapattackerwithtargetVectorState,
) -> BattleScriptSwapattackerwithtargetRules {
    BattleScriptSwapattackerwithtargetRules {
        selector_roles: BattleScriptSwapattackerwithtargetRoles {
            attacker: value.attacker,
            target: value.target,
            effect_battler: value.effect_battler,
            fainted: value.fainted,
        },
        scripting_battler: value.scripting_battler,
        hit_marker: value.hit_marker,
    }
}

fn vector_state(
    value: BattleScriptSwapattackerwithtargetRules,
) -> BattleScriptSwapattackerwithtargetVectorState {
    BattleScriptSwapattackerwithtargetVectorState {
        attacker: value.selector_roles.attacker,
        target: value.selector_roles.target,
        effect_battler: value.selector_roles.effect_battler,
        fainted: value.selector_roles.fainted,
        scripting_battler: value.scripting_battler,
        hit_marker: value.hit_marker,
    }
}

#[test]
fn complete_projected_outputs_controls_exact_errors_and_input_preservation_match_canonical_typescript(
) {
    assert_eq!(BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_CASES.len(), 579);
    for (case_index, case) in BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_CASES
        .iter()
        .enumerate()
    {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptSwapattackerwithtargetVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut current = input;
    let mut actual_controls = Vec::new();
    let mut actual_branches = Vec::new();
    let mut actual_error = None;

    for application in 0..case.applications {
        let prior = current;
        match apply_battle_script_swapattackerwithtarget(&current) {
            Ok(outcome) => {
                actual_controls.push(outcome.control);
                actual_branches.push(assert_transition_shape(
                    case_index,
                    case,
                    application,
                    prior,
                    outcome,
                ));
                current = outcome.rules;
            }
            Err(error) => {
                actual_error = Some(error.to_string());
                break;
            }
        }
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label,
    );
    match (actual_error, case.expected, case.expected_error) {
        (None, Some(expected), None) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: canonical control sequence",
                case.label,
            );
            assert_eq!(
                actual_branches.as_slice(),
                case.branches,
                "case {case_index} {}: canonical branch sequence",
                case.label,
            );
            assert_eq!(
                actual_controls.len(),
                usize::from(case.applications),
                "case {case_index} {}: successful sequence stopped early",
                case.label,
            );
            assert_eq!(
                vector_state(current),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
            if case.applications == 2 {
                assert_eq!(
                    current, input,
                    "case {case_index} {}: two swaps must restore complete narrow state",
                    case.label,
                );
            }
        }
        (Some(error), None, Some(expected_error)) => {
            assert!(
                actual_controls.is_empty(),
                "case {case_index} {}: error must not produce a control result",
                case.label,
            );
            assert!(
                actual_branches.is_empty(),
                "case {case_index} {}: error must not take a success branch",
                case.label,
            );
            assert_eq!(
                error, expected_error,
                "case {case_index} {}: exact canonical role error",
                case.label,
            );
        }
        (error, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: error={error:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptSwapattackerwithtargetVectorCase,
    application: u8,
    prior: BattleScriptSwapattackerwithtargetRules,
    outcome: BattleScriptSwapattackerwithtargetOutcome,
) -> &'static str {
    let attacker = prior.selector_roles.attacker.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: successful result had no attacker",
            case.label,
        )
    });
    let target = prior.selector_roles.target.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: successful result had no target",
            case.label,
        )
    });

    assert_eq!(
        outcome.control,
        BattleScriptSwapattackerwithtargetControl::Advance,
        "case {case_index} {} application {application}: operand-free source opcode must advance",
        case.label,
    );
    assert_eq!(
        outcome.rules.selector_roles.attacker,
        Some(target),
        "case {case_index} {} application {application}: attacker must become original target",
        case.label,
    );
    assert_eq!(
        outcome.rules.selector_roles.target,
        Some(attacker),
        "case {case_index} {} application {application}: target must become original attacker",
        case.label,
    );
    assert_eq!(
        outcome.rules.selector_roles.effect_battler, prior.selector_roles.effect_battler,
        "case {case_index} {} application {application}: effectBattler selector sibling changed",
        case.label,
    );
    assert_eq!(
        outcome.rules.selector_roles.fainted, prior.selector_roles.fainted,
        "case {case_index} {} application {application}: fainted selector sibling changed",
        case.label,
    );
    assert_eq!(
        outcome.rules.scripting_battler, prior.scripting_battler,
        "case {case_index} {} application {application}: scriptingBattler sibling changed",
        case.label,
    );
    assert_eq!(
        outcome.rules.hit_marker,
        prior.hit_marker ^ BATTLE_SCRIPT_HITMARKER_SWAP_ATTACKER_TARGET,
        "case {case_index} {} application {application}: hitMarker must XOR only bit 12",
        case.label,
    );
    assert_eq!(
        outcome.rules.hit_marker & !BATTLE_SCRIPT_HITMARKER_SWAP_ATTACKER_TARGET,
        prior.hit_marker & !BATTLE_SCRIPT_HITMARKER_SWAP_ATTACKER_TARGET,
        "case {case_index} {} application {application}: unrelated hitMarker bits changed",
        case.label,
    );
    "swap-attacker-target"
}

#[test]
fn complete_attacker_target_effect_and_fainted_matrix_is_covered() {
    let matrix = BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_CASES
        .iter()
        .filter(|case| case.category == "complete-attacker-target-effect-fainted-matrix")
        .collect::<Vec<_>>();
    assert_eq!(matrix.len(), 400);

    let role_value = |value: Option<BattleScriptSwapattackerwithtargetBattler>| {
        value.map_or(-1_i8, |battler| battler.as_u8() as i8)
    };
    let observed = matrix
        .iter()
        .map(|case| {
            (
                case.initial.attacker.expect("matrix attacker").as_u8(),
                case.initial.target.expect("matrix target").as_u8(),
                role_value(case.initial.effect_battler),
                role_value(case.initial.fainted),
            )
        })
        .collect::<BTreeSet<_>>();
    let expected = BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLER_DOMAIN
        .into_iter()
        .flat_map(|attacker| {
            BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLER_DOMAIN
                .into_iter()
                .flat_map(move |target| {
                    BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_OPTIONAL_SELECTOR_DOMAIN
                        .into_iter()
                        .flat_map(move |effect_battler| {
                            BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_OPTIONAL_SELECTOR_DOMAIN
                                .into_iter()
                                .map(move |fainted| (attacker, target, effect_battler, fainted))
                        })
                })
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed, expected);

    let pairs = matrix
        .iter()
        .map(|case| {
            (
                case.initial.attacker.expect("matrix attacker").as_u8(),
                case.initial.target.expect("matrix target").as_u8(),
            )
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(pairs.len(), 16, "all 4x4 attacker-target pairs");
    let scripting = matrix
        .iter()
        .map(|case| case.initial.scripting_battler.as_u8())
        .collect::<BTreeSet<_>>();
    assert_eq!(scripting, BTreeSet::from([0, 1, 2, 3]));
}

#[test]
fn every_pair_has_every_packed_u32_hit_marker_edge() {
    let edges = BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_CASES
        .iter()
        .filter(|case| case.category == "u32-hit-marker-edge-pair-matrix")
        .collect::<Vec<_>>();
    assert_eq!(edges.len(), 160);
    let observed = edges
        .iter()
        .map(|case| {
            (
                case.initial.attacker.expect("edge attacker").as_u8(),
                case.initial.target.expect("edge target").as_u8(),
                case.initial.hit_marker,
            )
        })
        .collect::<BTreeSet<_>>();
    let expected = BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLER_DOMAIN
        .into_iter()
        .flat_map(|attacker| {
            BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLER_DOMAIN
                .into_iter()
                .flat_map(move |target| {
                    BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_HIT_MARKER_EDGE_DOMAIN
                        .into_iter()
                        .map(move |hit_marker| (attacker, target, hit_marker))
                })
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed, expected);
    assert!(BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_HIT_MARKER_EDGE_DOMAIN.contains(&0));
    assert!(BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_HIT_MARKER_EDGE_DOMAIN.contains(&u32::MAX));
    assert!(BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_HIT_MARKER_EDGE_DOMAIN
        .iter()
        .any(|value| value & BATTLE_SCRIPT_HITMARKER_SWAP_ATTACKER_TARGET == 0));
    assert!(BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_HIT_MARKER_EDGE_DOMAIN
        .iter()
        .any(|value| value & BATTLE_SCRIPT_HITMARKER_SWAP_ATTACKER_TARGET != 0));
}

#[test]
fn aliases_ordered_errors_and_involution_are_pinned() {
    let aliases = BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_CASES
        .iter()
        .filter(|case| case.category == "explicit-selector-alias-permutations")
        .collect::<Vec<_>>();
    assert_eq!(aliases.len(), 16);
    for battler in BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLER_DOMAIN {
        let all_alias = aliases
            .iter()
            .find(|case| case.label == format!("alias_all_selector_roles_and_scripting_b{battler}"))
            .expect("all-role alias vector");
        let expected = BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLERS[usize::from(battler)];
        assert_eq!(all_alias.initial.attacker, Some(expected));
        assert_eq!(all_alias.initial.target, Some(expected));
        assert_eq!(all_alias.initial.effect_battler, Some(expected));
        assert_eq!(all_alias.initial.fainted, Some(expected));
        assert_eq!(all_alias.initial.scripting_battler, expected);
        assert_eq!(all_alias.expected, Some(all_alias.initial));
        assert_eq!(
            all_alias.controls,
            &[
                BattleScriptSwapattackerwithtargetControl::Advance,
                BattleScriptSwapattackerwithtargetControl::Advance,
            ],
        );
    }

    let ordered_errors = BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_CASES
        .iter()
        .filter(|case| case.category == "ordered-missing-selector-role-errors")
        .collect::<Vec<_>>();
    assert_eq!(ordered_errors.len(), 3);
    let both_missing = ordered_errors
        .iter()
        .find(|case| case.label == "missing_attacker_precedes_missing_target")
        .expect("doubly missing vector");
    assert_eq!(both_missing.initial.attacker, None);
    assert_eq!(both_missing.initial.target, None);
    assert_eq!(
        both_missing.expected_error,
        Some("Battle Script hit-chain command requires a attacker role"),
    );
    let missing_target = ordered_errors
        .iter()
        .find(|case| case.label == "missing_target_after_attacker_resolution")
        .expect("target-missing vector");
    assert!(missing_target.initial.attacker.is_some());
    assert_eq!(missing_target.initial.target, None);
    assert_eq!(
        missing_target.expected_error,
        Some("Battle Script hit-chain command requires a target role"),
    );
}

#[test]
fn source_domains_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLER_COUNT, 4);
    assert_eq!(
        BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLERS.map(|battler| battler.as_u8()),
        BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLER_DOMAIN,
    );
    assert_eq!(
        BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BATTLER_DOMAIN,
        [0, 1, 2, 3]
    );
    assert_eq!(
        BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_OPTIONAL_SELECTOR_DOMAIN,
        [-1, 0, 1, 2, 3],
    );
    assert_eq!(
        BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_HIT_MARKER_EDGE_DOMAIN,
        [
            0x0000_0000,
            0x0000_07ff,
            0x0000_0800,
            0x0000_0fff,
            0x0000_1000,
            0x0000_1001,
            0x0000_1fff,
            0xffff_efff,
            0x8000_1000,
            0xffff_ffff,
        ],
    );
    assert_eq!(BATTLE_SCRIPT_HITMARKER_SWAP_ATTACKER_TARGET, 0x0000_1000);
    assert_eq!(
        BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("attacker-role-values", 4),
            ("target-role-values", 4),
            ("optional-attacker-role-values", 5),
            ("optional-target-role-values", 5),
            ("optional-effect-battler-role-values", 5),
            ("optional-fainted-role-values", 5),
            ("scripting-battler-values", 4),
            ("hit-marker-u32-values", 4_294_967_296),
            ("hit-marker-swap-attacker-target-mask", 4_096),
            ("hit-marker-edge-values", 10),
            ("complete-attacker-target-pairs", 16),
            ("complete-attacker-target-effect-fainted-matrix-cases", 400),
            ("u32-hit-marker-edge-pair-matrix-cases", 160),
            ("explicit-selector-alias-cases", 16),
            ("ordered-missing-role-cases", 3),
            ("involution-application-count", 2),
            ("selector-roles-written-by-handler", 2),
            ("preserved-narrow-selector-siblings", 3),
            ("preserved-hit-marker-bit-count", 31),
            ("concrete-call-sites", 3),
            ("opcode-byte", 95),
            ("opcode-operands", 0),
            ("abi-exports-added", 0),
            ("unsupported-barriers-added", 0),
            ("generated-file-byte-limit-exclusive", 5_000_000),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_CATEGORY_CENSUS,
        [
            ("complete-attacker-target-effect-fainted-matrix", 400),
            ("explicit-selector-alias-permutations", 16),
            ("ordered-missing-selector-role-errors", 3),
            ("u32-hit-marker-edge-pair-matrix", 160),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_BRANCH_CENSUS,
        [
            ("missing-attacker-role", 2),
            ("missing-target-role", 1),
            (
                "swap-attacker-target-advance-then-swap-attacker-target-advance",
                576,
            ),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_SWAPATTACKERWITHTARGET_VECTOR_CORPUS_SHA256,
        "eb72926f0c8b959deb7766603f8978b8ab219e0ae9abc191646a02ef181ff76e",
    );
}
